import type { ComponentType, ReactNode } from 'react';

export type AiConfigEditorMode = 'form' | 'json';
export type AiConfigValidationMode = 'change' | 'submit';

export type AiConfigSafeParseResult<T> = { success: true; data: T } | { success: false; error: unknown };

export type AiConfigSchema<T> = {
	safeParse: (value: unknown) => AiConfigSafeParseResult<T>;
};

export type AiConfigEditorIssue = {
	path: string;
	message: string;
};

export type AiConfigFieldSlotProps<T> = {
	name: string;
	draft: T;
	disabled: boolean;
	readOnly: boolean;
	error?: string;
	defaultField: ReactNode;
	onDraftChange: (value: T) => void;
};

export type AiConfigEditorSlots<T> = {
	beforeForm?: ReactNode;
	afterForm?: ReactNode;
	headerActions?: ReactNode;
	fieldSlots?: Readonly<Record<string, ComponentType<AiConfigFieldSlotProps<T>>>>;
	summary?: ComponentType<AiConfigSummarySlotProps>;
};

export type AiConfigSummarySlotProps = {
	issues: readonly AiConfigEditorIssue[];
	defaultSummary: ReactNode;
};

export type AiConfigDraftController<T> = {
	draft: T;
	dirty: boolean;
	externalInvalid: boolean;
	externalError?: string;
	issues: readonly AiConfigEditorIssue[];
	visibleIssues: readonly AiConfigEditorIssue[];
	jsonText: string;
	jsonError?: string;
	canSubmit: boolean;
	setDraft: (value: T) => void;
	setJsonText: (value: string) => void;
	applyJson: () => boolean;
	reset: () => void;
	submit: () => boolean;
};

export type AiConfigEditorMessages = {
	formMode: string;
	jsonMode: string;
	reset: string;
	submit: string;
	applyJson: string;
	invalidExternalTitle: string;
	invalidExternalDescription: string;
	invalidJson: string;
	validationTitle: string;
	validationCount: (count: number) => string;
	jsonLabel: string;
	readOnly: string;
};

export type AiConfigEditorMessageOverrides = Partial<AiConfigEditorMessages>;

export type AiConfigEditorOption = {
	value: string;
	label: string;
	description?: string;
	disabled?: boolean;
};

export type AiResourceEditorMessages<Field extends string, Section extends string> = {
	title: string;
	description: string;
	fields: Record<Field, string>;
	sections: Record<Section, string>;
	editor?: AiConfigEditorMessageOverrides;
};

export type AiResourceEditorMessageOverrides<Field extends string, Section extends string> = {
	title?: string;
	description?: string;
	fields?: Partial<Record<Field, string>>;
	sections?: Partial<Record<Section, string>>;
	editor?: AiConfigEditorMessageOverrides;
};

export function mergeResourceEditorMessages<Field extends string, Section extends string>(
	defaults: AiResourceEditorMessages<Field, Section>,
	overrides?: AiResourceEditorMessageOverrides<Field, Section>,
): AiResourceEditorMessages<Field, Section> {
	return {
		title: overrides?.title ?? defaults.title,
		description: overrides?.description ?? defaults.description,
		fields: { ...defaults.fields, ...overrides?.fields },
		sections: { ...defaults.sections, ...overrides?.sections },
		editor: { ...defaults.editor, ...overrides?.editor },
	};
}

import type { AiConfigEditorMessageOverrides, AiConfigEditorMessages } from './ai-config-types';

export const defaultAiConfigEditorMessages: AiConfigEditorMessages = {
	formMode: '表单',
	jsonMode: 'JSON',
	reset: '重置',
	submit: '应用配置',
	applyJson: '应用 JSON',
	invalidExternalTitle: '外部配置无效',
	invalidExternalDescription: '当前显示安全回退草稿；原始值未被修改。修正后才会发出变更。',
	invalidJson: 'JSON 内容无法解析或不符合配置约束。',
	validationTitle: '请检查以下配置问题',
	validationCount: (count) => `${count} 个问题`,
	jsonLabel: '配置 JSON',
	readOnly: '只读',
};

export function mergeAiConfigEditorMessages(overrides?: AiConfigEditorMessageOverrides): AiConfigEditorMessages {
	return { ...defaultAiConfigEditorMessages, ...overrides };
}

import type { AiConfigEditorIssue, AiConfigSafeParseResult, AiConfigSchema } from './ai-config-types';

export function safeParseAiConfig<T>(schema: AiConfigSchema<T>, value: unknown): AiConfigSafeParseResult<T> {
	try {
		return schema.safeParse(value);
	} catch (error) {
		return { success: false, error };
	}
}

export function aiConfigIssues(error: unknown): AiConfigEditorIssue[] {
	const issueValues = readIssueArray(error);
	if (!issueValues) return [{ path: '', message: errorMessage(error) }];
	const issues = issueValues.map(toEditorIssue).filter((issue): issue is AiConfigEditorIssue => Boolean(issue));
	return issues.length ? issues : [{ path: '', message: errorMessage(error) }];
}

export function aiConfigFieldError(issues: readonly AiConfigEditorIssue[], path: string): string | undefined {
	return issues.find((issue) => issue.path === path || issue.path.startsWith(`${path}.`))?.message;
}

export function stringifyAiConfig(value: unknown, indentation = 2): string {
	try {
		return JSON.stringify(value, null, indentation) ?? 'null';
	} catch {
		return '';
	}
}

export function compactAiConfig(value: unknown): string {
	return stringifyAiConfig(value, 0);
}

function readIssueArray(error: unknown): unknown[] | undefined {
	if (!isRecord(error) || !Array.isArray(error.issues)) return undefined;
	return error.issues;
}

function toEditorIssue(value: unknown): AiConfigEditorIssue | undefined {
	if (!isRecord(value)) return undefined;
	const path = Array.isArray(value.path) ? value.path.map(String).join('.') : '';
	const message = typeof value.message === 'string' ? value.message : '配置值无效';
	return { path, message };
}

function errorMessage(error: unknown): string {
	if (error instanceof Error && error.message) return error.message;
	if (typeof error === 'string' && error) return error;
	return '配置值无效';
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === 'object' && value !== null;
}

'use client';

import { useCallback, useEffect, useMemo, useState } from 'react';
import type {
	AiConfigDraftController,
	AiConfigEditorIssue,
	AiConfigSchema,
	AiConfigValidationMode,
} from './ai-config-types';
import { aiConfigIssues, compactAiConfig, safeParseAiConfig, stringifyAiConfig } from './ai-config-validation';

export type UseAiConfigDraftOptions<T> = {
	value: T;
	fallbackValue: T;
	schema: AiConfigSchema<T>;
	onChange: (value: T) => void;
	onSubmit?: (value: T) => void;
	validationMode?: AiConfigValidationMode;
};

type InitialDraft<T> = {
	draft: T;
	externalInvalid: boolean;
	externalError?: string;
	issues: AiConfigEditorIssue[];
};

export function useAiConfigDraft<T>({
	value,
	fallbackValue,
	schema,
	onChange,
	onSubmit,
	validationMode = 'change',
}: UseAiConfigDraftOptions<T>): AiConfigDraftController<T> {
	const initial = useMemo(() => initialDraft(schema, value, fallbackValue), [fallbackValue, schema, value]);
	const [draft, setDraftState] = useState(initial.draft);
	const [externalInvalid, setExternalInvalid] = useState(initial.externalInvalid);
	const [externalError, setExternalError] = useState(initial.externalError);
	const [issues, setIssues] = useState<AiConfigEditorIssue[]>(initial.issues);
	const [submitted, setSubmitted] = useState(false);
	const [jsonText, setJsonTextState] = useState(() => stringifyAiConfig(initial.draft));
	const [jsonError, setJsonError] = useState<string>();
	const externalDraft = initial.draft;

	useEffect(() => {
		setDraftState(initial.draft);
		setExternalInvalid(initial.externalInvalid);
		setExternalError(initial.externalError);
		setIssues(initial.issues);
		setJsonTextState(stringifyAiConfig(initial.draft));
		setJsonError(undefined);
		setSubmitted(false);
	}, [initial]);

	const setDraft = useCallback(
		(next: T) => {
			setDraftState(next);
			setJsonTextState(stringifyAiConfig(next));
			setJsonError(undefined);
			const parsed = safeParseAiConfig(schema, next);
			if (!parsed.success) {
				setIssues(aiConfigIssues(parsed.error));
				return;
			}
			setIssues([]);
			onChange(parsed.data);
		},
		[onChange, schema],
	);

	const setJsonText = useCallback((next: string) => {
		setJsonTextState(next);
		setJsonError(undefined);
	}, []);

	const applyJson = useCallback(() => {
		let candidate: unknown;
		try {
			candidate = JSON.parse(jsonText);
		} catch (error) {
			setJsonError(error instanceof Error ? error.message : 'JSON parse failed');
			return false;
		}
		const parsed = safeParseAiConfig(schema, candidate);
		if (!parsed.success) {
			const nextIssues = aiConfigIssues(parsed.error);
			setIssues(nextIssues);
			setJsonError(nextIssues[0]?.message ?? 'Invalid configuration');
			return false;
		}
		setDraftState(parsed.data);
		setIssues([]);
		setJsonError(undefined);
		setJsonTextState(stringifyAiConfig(parsed.data));
		onChange(parsed.data);
		return true;
	}, [jsonText, onChange, schema]);

	const reset = useCallback(() => {
		setDraftState(externalDraft);
		setIssues(initial.issues);
		setJsonTextState(stringifyAiConfig(externalDraft));
		setJsonError(undefined);
		setSubmitted(false);
	}, [externalDraft, initial.issues]);

	const submit = useCallback(() => {
		setSubmitted(true);
		const parsed = safeParseAiConfig(schema, draft);
		if (!parsed.success) {
			setIssues(aiConfigIssues(parsed.error));
			return false;
		}
		setIssues([]);
		onSubmit?.(parsed.data);
		return true;
	}, [draft, onSubmit, schema]);

	const dirty = compactAiConfig(draft) !== compactAiConfig(externalDraft);
	const visibleIssues = validationMode === 'change' || submitted ? issues : [];
	return {
		draft,
		dirty,
		externalInvalid,
		externalError,
		issues,
		visibleIssues,
		jsonText,
		jsonError,
		canSubmit: issues.length === 0,
		setDraft,
		setJsonText,
		applyJson,
		reset,
		submit,
	};
}

function initialDraft<T>(schema: AiConfigSchema<T>, value: T, fallbackValue: T): InitialDraft<T> {
	const parsed = safeParseAiConfig(schema, value);
	if (parsed.success) return { draft: parsed.data, externalInvalid: false, issues: [] };
	const fallback = safeParseAiConfig(schema, fallbackValue);
	const issues = aiConfigIssues(parsed.error);
	return {
		draft: fallback.success ? fallback.data : fallbackValue,
		externalInvalid: true,
		externalError: issues[0]?.message,
		issues,
	};
}

'use client';

import { useLayoutEffect, useState } from 'react';

export type StableListEntry<T> = { item: T; key: string };

export function useStableListEntries<T>(items: readonly T[], prefix = 'item'): StableListEntry<T>[] {
	const [committed, setCommitted] = useState<StableListState<T>>(() =>
		projectStableList(emptyStableList(prefix), items, prefix),
	);
	const projected = projectStableList(committed, items, prefix);
	useLayoutEffect(() => {
		setCommitted((current) =>
			sameStableList(current, items, prefix) ? current : projectStableList(current, items, prefix),
		);
	}, [items, prefix]);
	return items.map((item, index) => ({ item, key: projected.keys[index] }));
}

type StableListState<T> = {
	items: readonly T[];
	keys: readonly string[];
	prefix: string;
	sequence: number;
};

function emptyStableList<T>(prefix: string): StableListState<T> {
	return { items: [], keys: [], prefix, sequence: 0 };
}

function projectStableList<T>(previous: StableListState<T>, items: readonly T[], prefix: string): StableListState<T> {
	const keys: Array<string | undefined> = new Array(items.length);
	const usedPrevious = new Set<number>();
	let sequence = previous.sequence;

	for (const [index, item] of items.entries()) {
		const previousIndex = previous.items.findIndex(
			(candidate, candidateIndex) => !usedPrevious.has(candidateIndex) && Object.is(candidate, item),
		);
		if (previousIndex < 0) continue;
		keys[index] = previous.keys[previousIndex];
		usedPrevious.add(previousIndex);
	}

	for (const index of items.keys()) {
		if (keys[index]) continue;
		if (index < previous.keys.length && !usedPrevious.has(index)) {
			keys[index] = previous.keys[index];
			usedPrevious.add(index);
		} else {
			keys[index] = `${prefix}-${++sequence}`;
		}
	}

	return { items: [...items], keys: keys as string[], prefix, sequence };
}

function sameStableList<T>(state: StableListState<T>, items: readonly T[], prefix: string) {
	return (
		state.prefix === prefix &&
		state.items.length === items.length &&
		state.items.every((item, index) => Object.is(item, items[index]))
	);
}

'use client';

import { Eye, EyeOff, X } from 'lucide-react';
import type { ComponentPropsWithRef, ReactNode } from 'react';
import { useEffect, useId, useState } from 'react';
import type { AiConfigEditorOption } from './ai-config-types';

export type AiConfigFieldBase = {
	label: string;
	description?: string;
	error?: string;
	required?: boolean;
	wrapperClassName?: string;
};

export type AiConfigTextFieldProps = Omit<ComponentPropsWithRef<'input'>, 'value' | 'onChange' | 'type'> &
	AiConfigFieldBase & {
		value?: string;
		onValueChange: (value: string) => void;
		type?: 'text' | 'url' | 'date' | 'email';
	};

export function AiConfigTextField({
	label,
	description,
	error,
	required,
	wrapperClassName,
	value = '',
	onValueChange,
	className,
	id: providedId,
	...props
}: AiConfigTextFieldProps) {
	const generatedId = useId();
	const id = providedId ?? generatedId;
	const errorId = error ? `${id}-error` : undefined;
	return (
		<AiConfigFieldFrame
			label={label}
			description={description}
			error={error}
			errorId={errorId}
			required={required}
			className={wrapperClassName}
			htmlFor={id}
		>
			<input
				id={id}
				className={`input input-bordered w-full min-w-0 ${className ?? ''}`}
				aria-invalid={Boolean(error) || undefined}
				aria-describedby={errorId}
				value={value}
				onChange={(event) => onValueChange(event.target.value)}
				{...props}
			/>
		</AiConfigFieldFrame>
	);
}

export type AiConfigTextareaFieldProps = Omit<ComponentPropsWithRef<'textarea'>, 'value' | 'onChange'> &
	AiConfigFieldBase & {
		value?: string;
		onValueChange: (value: string) => void;
	};

export function AiConfigTextareaField({
	label,
	description,
	error,
	required,
	wrapperClassName,
	value = '',
	onValueChange,
	className,
	id: providedId,
	rows = 4,
