	const generatedId = useId();
	const id = providedId ?? generatedId;
	const errorId = error ? `${id}-error` : undefined;
	return (
		<AiConfigFieldFrame
			label={label}
			description={description}
			error={error}
			errorId={errorId}
			required={required}
			className={wrapperClassName}
			htmlFor={id}
		>
			<textarea
				id={id}
				className={`textarea textarea-bordered w-full min-w-0 ${className ?? ''}`}
				aria-invalid={Boolean(error) || undefined}
				aria-describedby={errorId}
				rows={rows}
				value={value}
				onChange={(event) => onValueChange(event.target.value)}
				{...props}
			/>
		</AiConfigFieldFrame>
	);
}

export type AiConfigSelectFieldProps = Omit<ComponentPropsWithRef<'select'>, 'value' | 'onChange'> &
	AiConfigFieldBase & {
		value?: string;
		onValueChange: (value: string) => void;
		options: readonly AiConfigEditorOption[];
		placeholder?: string;
	};

export function AiConfigSelectField({
	label,
	description,
	error,
	required,
	wrapperClassName,
	value = '',
	onValueChange,
	options,
	placeholder = '请选择',
	className,
	id: providedId,
	...props
}: AiConfigSelectFieldProps) {
	const generatedId = useId();
	const id = providedId ?? generatedId;
	const errorId = error ? `${id}-error` : undefined;
	const known = !value || options.some((option) => option.value === value);
	return (
		<AiConfigFieldFrame
			label={label}
			description={description}
			error={error}
			errorId={errorId}
			required={required}
			className={wrapperClassName}
			htmlFor={id}
		>
			<select
				id={id}
				className={`select select-bordered w-full min-w-0 ${className ?? ''}`}
				aria-invalid={Boolean(error) || undefined}
				aria-describedby={errorId}
				value={value}
				onChange={(event) => onValueChange(event.target.value)}
				{...props}
			>
				<option value=''>{placeholder}</option>
				{!known ? <option value={value}>{value}（当前值）</option> : null}
				{options.map((option) => (
					<option key={option.value} value={option.value} disabled={option.disabled}>
						{option.label}
					</option>
				))}
			</select>
		</AiConfigFieldFrame>
	);
}

export type AiConfigNumberFieldProps = Omit<ComponentPropsWithRef<'input'>, 'value' | 'onChange' | 'type'> &
	AiConfigFieldBase & {
		value?: number | null;
		onValueChange: (value: number | undefined) => void;
		integer?: boolean;
	};

export function AiConfigNumberField({
	label,
	description,
	error,
	required,
	wrapperClassName,
	value,
	onValueChange,
	integer = false,
	className,
	id: providedId,
	...props
}: AiConfigNumberFieldProps) {
	const generatedId = useId();
	const id = providedId ?? generatedId;
	const external = value === undefined || value === null ? '' : String(value);
	const [draft, setDraft] = useState(external);
	useEffect(() => setDraft(external), [external]);
	const issueId = error ? `${id}-error` : undefined;
	return (
		<AiConfigFieldFrame
			label={label}
			description={description}
			error={error}
			errorId={issueId}
			required={required}
			className={wrapperClassName}
			htmlFor={id}
		>
			<input
				id={id}
				type='number'
				step={integer ? 1 : 'any'}
				className={`input input-bordered w-full min-w-0 ${className ?? ''}`}
				aria-invalid={Boolean(error) || undefined}
				aria-describedby={issueId}
				value={draft}
				onChange={(event) => {
					const next = event.target.value;
					setDraft(next);
					if (next === '') onValueChange(undefined);
					else {
						const number = Number(next);
						if (Number.isFinite(number) && (!integer || Number.isInteger(number))) onValueChange(number);
					}
				}}
				{...props}
			/>
		</AiConfigFieldFrame>
	);
}

export type AiConfigToggleFieldProps = Omit<ComponentPropsWithRef<'input'>, 'checked' | 'onChange' | 'type'> &
	AiConfigFieldBase & {
		checked: boolean;
		onCheckedChange: (checked: boolean) => void;
	};

export function AiConfigToggleField({
	label,
	description,
	error,
	wrapperClassName,
	checked,
	onCheckedChange,
	className,
	id: providedId,
	...props
}: AiConfigToggleFieldProps) {
	const generatedId = useId();
	const id = providedId ?? generatedId;
	return (
		<div className={`min-w-0 ${wrapperClassName ?? ''}`}>
			<label
				htmlFor={id}
				className='border-base-300 flex min-h-12 cursor-pointer items-center gap-3 rounded-sm border px-3 py-2'
			>
				<span className='min-w-0 flex-1'>
					<span className='block text-sm font-medium'>{label}</span>
					{description ? <span className='text-base-content/60 block text-xs'>{description}</span> : null}
				</span>
				<input
					id={id}
					type='checkbox'
					className={`toggle toggle-sm ${className ?? ''}`}
					checked={checked}
					onChange={(event) => onCheckedChange(event.target.checked)}
					{...props}
				/>
			</label>
			{error ? (
				<p className='text-error mt-1 text-xs' role='alert'>
					{error}
				</p>
			) : null}
		</div>
	);
}

export type AiConfigSecretFieldProps = Omit<AiConfigTextFieldProps, 'type'> & {
	clearLabel?: string;
	revealLabel?: string;
	hideLabel?: string;
	revealIdentity?: number | string;
};

export function AiConfigSecretField({
	label,
	value = '',
	onValueChange,
	clearLabel = '清除密钥',
	revealLabel = '显示密钥',
	hideLabel = '隐藏密钥',
	revealIdentity,
	description,
	error,
	required,
	wrapperClassName,
	className,
	id: providedId,
	readOnly,
	disabled,
	...inputProps
}: AiConfigSecretFieldProps) {
	const [revealed, setRevealed] = useState(false);
	useEffect(() => setRevealed(false), [revealIdentity]);
	const generatedId = useId();
	const id = providedId ?? generatedId;
	const errorId = error ? `${id}-error` : undefined;
	return (
		<AiConfigFieldFrame
			label={label}
			description={description}
			error={error}
			errorId={errorId}
			required={required}
			htmlFor={id}
			className={wrapperClassName}
		>
			<div className='join flex w-full'>
				<input
					id={id}
					type={revealed ? 'text' : 'password'}
					className={`input input-bordered join-item min-w-0 flex-1 font-mono ${className ?? ''}`}
					aria-invalid={Boolean(error) || undefined}
					aria-describedby={errorId}
					value={value}
					readOnly={readOnly}
					disabled={disabled}
					autoComplete='off'
					onChange={(event) => onValueChange(event.target.value)}
					{...inputProps}
				/>
				<button
					type='button'
					className='btn btn-outline join-item btn-square'
					title={revealed ? hideLabel : revealLabel}
					aria-label={revealed ? hideLabel : revealLabel}
					disabled={disabled}
					onClick={() => setRevealed((current) => !current)}
				>
					{revealed ? <EyeOff aria-hidden='true' className='size-4' /> : <Eye aria-hidden='true' className='size-4' />}
				</button>
				{!readOnly ? (
					<button
						type='button'
						className='btn btn-outline join-item btn-square'
						title={clearLabel}
						aria-label={clearLabel}
						disabled={disabled || !value}
						onClick={() => onValueChange('')}
					>
						<X aria-hidden='true' className='size-4' />
					</button>
				) : null}
			</div>
		</AiConfigFieldFrame>
	);
}

export type AiConfigFieldFrameProps = ComponentPropsWithRef<'div'> & {
	label: string;
	description?: string;
	error?: string;
	errorId?: string;
	required?: boolean;
	htmlFor?: string;
	children: ReactNode;
};

export function AiConfigFieldFrame({
	label,
	description,
	error,
	errorId,
	required,
	htmlFor,
	children,
	className,
	...props
}: AiConfigFieldFrameProps) {
	return (
		<div className={`min-w-0 ${className ?? ''}`} {...props}>
			<label htmlFor={htmlFor} className='mb-1 block text-sm font-medium'>
				{label}
				{required ? (
					<span className='text-error ms-1' aria-hidden='true'>
						*
					</span>
				) : null}
			</label>
			{description ? <p className='text-base-content/60 mb-1 text-xs'>{description}</p> : null}
			{children}
			{error ? (
				<p id={errorId} className='text-error mt-1 text-xs' role='alert'>
					{error}
				</p>
			) : null}
		</div>
	);
}

'use client';

import { Plus, Trash2, X } from 'lucide-react';
import type { ComponentPropsWithRef, KeyboardEvent } from 'react';
import { useEffect, useId, useRef, useState } from 'react';
import { AiConfigFieldFrame } from './ai-config-fields';
import { useStableListEntries } from './use-stable-list-entries';

export type AiConfigStringListFieldProps = Omit<ComponentPropsWithRef<'div'>, 'onChange'> & {
	label: string;
	value?: readonly string[];
	onChange: (value: string[]) => void;
	description?: string;
	error?: string;
	placeholder?: string;
	addLabel?: string;
	removeLabel?: (value: string) => string;
	disabled?: boolean;
	readOnly?: boolean;
	maxItems?: number;
};

export function AiConfigStringListField({
	label,
	value = [],
	onChange,
	description,
	error,
	placeholder = '输入后按回车',
	addLabel = '添加',
	removeLabel = (item) => `移除 ${item}`,
	disabled = false,
	readOnly = false,
	maxItems = 128,
	className,
	...props
}: AiConfigStringListFieldProps) {
	const id = useId();
	const composing = useRef(false);
	const [draft, setDraft] = useState('');
	const entries = useStableListEntries(value, 'string-list-item');
	const add = () => {
		const next = draft.trim();
		if (!next || value.includes(next) || value.length >= maxItems) return;
		onChange([...value, next]);
		setDraft('');
	};
	return (
		<AiConfigFieldFrame
			label={label}
			description={description}
			error={error}
			htmlFor={id}
			className={className}
			{...props}
		>
			{!readOnly ? (
				<div className='flex min-w-0 gap-2'>
					<input
						id={id}
						className='input input-bordered min-w-0 flex-1'
						placeholder={placeholder}
						value={draft}
						disabled={disabled || value.length >= maxItems}
						onChange={(event) => setDraft(event.target.value)}
						onCompositionStart={() => {
							composing.current = true;
						}}
						onCompositionEnd={() => {
							composing.current = false;
						}}
						onKeyDown={(event) => submitOnEnter(event, add, composing.current)}
					/>
					<button
						type='button'
						className='btn btn-outline btn-square'
						title={addLabel}
						aria-label={addLabel}
						disabled={disabled || !draft.trim() || value.length >= maxItems}
						onClick={add}
					>
						<Plus aria-hidden='true' className='size-4' />
					</button>
				</div>
			) : null}
			<div className='mt-2 flex min-h-7 min-w-0 flex-wrap gap-1.5'>
				{value.length ? (
					entries.map(({ item, key }, index) => (
						<span key={key} className='badge badge-outline h-7 max-w-full gap-1 pe-1'>
							<span className='truncate'>{item}</span>
							{!readOnly ? (
								<button
									type='button'
									className='hover:bg-base-200 grid size-5 shrink-0 place-items-center rounded-full'
									title={removeLabel(item)}
									aria-label={removeLabel(item)}
									disabled={disabled}
									onClick={() => onChange(value.filter((_, itemIndex) => itemIndex !== index))}
								>
									<X aria-hidden='true' className='size-3' />
								</button>
							) : null}
						</span>
					))
				) : (
					<span className='text-base-content/50 text-xs'>暂无条目</span>
				)}
			</div>
		</AiConfigFieldFrame>
	);
}

export type AiConfigKeyValueFieldProps = Omit<ComponentPropsWithRef<'div'>, 'onChange'> & {
	label: string;
	value?: Readonly<Record<string, string>>;
	onChange: (value: Record<string, string>) => void;
	description?: string;
	error?: string;
	keyLabel?: string;
	valueLabel?: string;
	addLabel?: string;
	removeLabel?: (key: string) => string;
	disabled?: boolean;
	readOnly?: boolean;
	maxItems?: number;
};

export function AiConfigKeyValueField({
	label,
	value = {},
	onChange,
	description,
	error,
	keyLabel = '键',
	valueLabel = '值',
	addLabel = '添加键值',
	removeLabel = (key) => `移除 ${key}`,
	disabled = false,
	readOnly = false,
	maxItems = 128,
	className,
	...props
}: AiConfigKeyValueFieldProps) {
	const composing = useRef(false);
	const [newKey, setNewKey] = useState('');
	const [newValue, setNewValue] = useState('');
	const entries = Object.entries(value);
	const add = () => {
		const key = newKey.trim();
		if (!key || Object.hasOwn(value, key) || entries.length >= maxItems) return;
		onChange(withAiConfigMapEntry(value, key, newValue));
		setNewKey('');
		setNewValue('');
	};
	return (
		<AiConfigFieldFrame label={label} description={description} error={error} className={className} {...props}>
			<div className='space-y-1.5'>
				{entries.map(([key, entryValue]) => (
					<AiConfigMapRow
						key={key}
						entryKey={key}
						entryValue={entryValue}
						keyLabel={keyLabel}
						valueLabel={valueLabel}
						disabled={disabled}
						readOnly={readOnly}
						onCommit={(nextKey, nextValue) => {
							if (!nextKey || (nextKey !== key && Object.hasOwn(value, nextKey))) return;
							onChange(withAiConfigMapEntry(value, nextKey, nextValue, key));
						}}
						onRemove={() => onChange(withoutAiConfigMapEntry(value, key))}
						removeLabel={removeLabel(key)}
					/>
				))}
			</div>
			{!readOnly ? (
				<div className='mt-2 grid min-w-0 grid-cols-[minmax(0,.8fr)_minmax(0,1.2fr)_auto] gap-1.5'>
					<input
						className='input input-bordered min-w-0'
						aria-label={`${label} ${keyLabel}`}
						placeholder={keyLabel}
						value={newKey}
						disabled={disabled || entries.length >= maxItems}
						onChange={(event) => setNewKey(event.target.value)}
					/>
					<input
						className='input input-bordered min-w-0'
						aria-label={`${label} ${valueLabel}`}
						placeholder={valueLabel}
						value={newValue}
						disabled={disabled || entries.length >= maxItems}
						onChange={(event) => setNewValue(event.target.value)}
						onCompositionStart={() => {
							composing.current = true;
						}}
						onCompositionEnd={() => {
							composing.current = false;
						}}
						onKeyDown={(event) => submitOnEnter(event, add, composing.current)}
					/>
					<button
						type='button'
						className='btn btn-outline btn-square'
						title={addLabel}
						aria-label={addLabel}
						disabled={disabled || !newKey.trim() || entries.length >= maxItems}
						onClick={add}
					>
						<Plus aria-hidden='true' className='size-4' />
					</button>
				</div>
			) : null}
		</AiConfigFieldFrame>
	);
}

type AiConfigMapRowProps = {
	entryKey: string;
	entryValue: string;
	keyLabel: string;
	valueLabel: string;
	disabled: boolean;
	readOnly: boolean;
	removeLabel: string;
	onCommit: (key: string, value: string) => void;
	onRemove: () => void;
};

function AiConfigMapRow({
	entryKey,
	entryValue,
	keyLabel,
	valueLabel,
	disabled,
	readOnly,
	removeLabel,
	onCommit,
	onRemove,
}: AiConfigMapRowProps) {
	const [keyDraft, setKeyDraft] = useState(entryKey);
	const [valueDraft, setValueDraft] = useState(entryValue);
	useEffect(() => setKeyDraft(entryKey), [entryKey]);
	useEffect(() => setValueDraft(entryValue), [entryValue]);
	if (readOnly)
		return (
			<div className='border-base-300 grid grid-cols-[minmax(0,.8fr)_minmax(0,1.2fr)] gap-2 rounded-sm border px-2 py-1.5 text-sm'>
				<code className='truncate'>{entryKey}</code>
				<span className='truncate'>{entryValue}</span>
			</div>
		);
	return (
		<div className='grid min-w-0 grid-cols-[minmax(0,.8fr)_minmax(0,1.2fr)_auto] gap-1.5'>
			<input
				className='input input-bordered input-sm min-w-0 font-mono'
				aria-label={keyLabel}
				value={keyDraft}
				disabled={disabled}
				onChange={(event) => setKeyDraft(event.target.value)}
				onBlur={() => onCommit(keyDraft.trim(), valueDraft)}
			/>
			<input
				className='input input-bordered input-sm min-w-0'
				aria-label={valueLabel}
				value={valueDraft}
				disabled={disabled}
				onChange={(event) => {
					const next = event.target.value;
					setValueDraft(next);
					onCommit(keyDraft.trim(), next);
				}}
			/>
			<button
				type='button'
				className='btn btn-ghost btn-sm btn-square text-error'
				title={removeLabel}
				aria-label={removeLabel}
				disabled={disabled}
				onClick={onRemove}
			>
				<Trash2 aria-hidden='true' className='size-4' />
			</button>
		</div>
	);
}

export function withAiConfigMapEntry(
	value: Readonly<Record<string, string>>,
	key: string,
	entryValue: string,
	previousKey?: string,
): Record<string, string> {
	const next = copyAiConfigMap(value, previousKey);
	Object.defineProperty(next, key, { value: entryValue, enumerable: true, configurable: true, writable: true });
	return next;
}

export function withoutAiConfigMapEntry(value: Readonly<Record<string, string>>, key: string): Record<string, string> {
	return copyAiConfigMap(value, key);
}

function copyAiConfigMap(value: Readonly<Record<string, string>>, omittedKey?: string): Record<string, string> {
	const next = Object.create(null) as Record<string, string>;
	for (const [key, entryValue] of Object.entries(value)) {
		if (key === omittedKey) continue;
		Object.defineProperty(next, key, { value: entryValue, enumerable: true, configurable: true, writable: true });
	}
	return next;
}

function submitOnEnter(event: KeyboardEvent<HTMLInputElement>, submit: () => void, composing: boolean) {
	if (event.key !== 'Enter' || composing || event.nativeEvent.isComposing) return;
	event.preventDefault();
	submit();
}

